<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { cambiarHorarioDetalle, obtenerDetalleProgramacion } from '../services/programacionesHorario'
import type { HorarioTrabajo } from '../interfaces/horario.interface'
import type { ProgramacionHorario, ProgramacionHorarioDetalle, TrabajadorDetalleProgramacion } from '../interfaces/programacionHorario.interface'
const route=useRoute(),id=computed(()=>Number(route.query.id||0)),programacion=ref<ProgramacionHorario|null>(null),rows=ref<TrabajadorDetalleProgramacion[]>([]),horarios=ref<HorarioTrabajo[]>([]),busqueda=ref(''),fecha=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),from=ref<number|null>(null),to=ref<number|null>(null),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),editing=ref<ProgramacionHorarioDetalle|null>(null),horarioId=ref(0)
const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.',date=(v:string)=>new Date(`${v}T00:00:00`).toLocaleDateString('es-PE',{weekday:'short',day:'2-digit',month:'2-digit',year:'numeric'}),time=(v:string|null)=>v?v.slice(0,5):'—'
async function load(next=1){if(!id.value)return void(error.value='Indique la programación mediante ?id=.');loading.value=true;error.value='';try{const r=await obtenerDetalleProgramacion(id.value,busqueda.value,fecha.value,next);programacion.value=r.programacion;rows.value=r.data;horarios.value=r.horarios;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total;from.value=r.from;to.value=r.to}catch(v){error.value=message(v)}finally{loading.value=false}}
function open(item:ProgramacionHorarioDetalle){editing.value=item;horarioId.value=item.horario_id;error.value=''}
async function save(){if(!editing.value||!horarioId.value)return;saving.value=true;try{await cambiarHorarioDetalle(editing.value.id,horarioId.value);success.value='Horario actualizado correctamente.';editing.value=null;await load(page.value)}catch(v){error.value=message(v)}finally{saving.value=false}}
function clear(){busqueda.value='';fecha.value='';load(1)}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/administracion/recursos/programacion-horarios">Programaciones</RouterLink> / Detalle</nav><header v-if="programacion" class="hero"><div class="mark">#{{programacion.id}}</div><div><small>CONTROL DE TIEMPOS · {{programacion.regimen?.codigo}}</small><h1>Detalle de programación</h1><p>{{date(programacion.fecha_inicio)}} al {{date(programacion.fecha_fin)}}</p></div><RouterLink to="/modulos/administracion/recursos/programacion-horarios">Volver</RouterLink></header><section v-if="programacion" class="facts"><div><b>Régimen</b><span>{{programacion.regimen?.descripcion||'—'}}</span></div><div><b>Trabajadores</b><span>{{programacion.total_trabajadores}}</span></div><div><b>Registros diarios</b><span>{{programacion.total_registros}}</span></div><div><b>Observación</b><span>{{programacion.observacion||'Sin observación'}}</span></div></section><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error&&!editing" class="flash error">{{error}}</p><form class="filters" @submit.prevent="load(1)"><input v-model.trim="busqueda" placeholder="Apellidos o nombre"><input v-model="fecha" type="date"><button>Filtrar</button><button type="button" class="soft" @click="clear">Limpiar</button></form><div v-if="loading" class="empty">Consultando jornadas…</div><div v-else-if="!rows.length" class="empty">No se encontraron registros con los filtros aplicados.</div><article v-for="worker in rows" v-else :key="worker.id"><header><div><b>{{worker.codigo_trabajador}}</b> {{worker.nombre_completo}}</div><small>{{worker.detalles.length}} días</small></header><div class="scroll"><table><thead><tr><th>Fecha</th><th>Horario</th><th>Entrada 1</th><th>Salida 1</th><th>Entrada 2</th><th>Salida 2</th><th>Horas</th><th>Acción</th></tr></thead><tbody><tr v-for="detail in worker.detalles" :key="detail.id"><td>{{date(detail.fecha)}}</td><td><b>{{detail.horario?.codigo||'—'}}</b> {{detail.horario?.descripcion}}</td><td>{{time(detail.entrada_1)}}</td><td>{{time(detail.salida_1)}}</td><td>{{time(detail.entrada_2)}}</td><td>{{time(detail.salida_2)}}</td><td>{{Number(detail.horas_programadas).toFixed(2)}}</td><td><button @click="open(detail)">Cambiar</button></td></tr></tbody></table></div></article><footer v-if="lastPage>1" class="pager"><small>Trabajadores {{from||0}}–{{to||0}} de {{total}}</small><div><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></div></footer><div v-if="editing" class="overlay" @click.self="editing=null"><section class="modal"><header><div><small>CAMBIAR HORARIO</small><h2>{{date(editing.fecha)}}</h2></div><button @click="editing=null">×</button></header><p v-if="error" class="flash error">{{error}}</p><div class="current"><b>Horario actual</b><span>{{editing.horario?.codigo}} · {{editing.horario?.descripcion}}</span><small>{{time(editing.entrada_1)}} / {{time(editing.salida_1)}} · {{Number(editing.horas_programadas).toFixed(2)}} h</small></div><label>Nuevo horario<select v-model="horarioId"><option :value="0">Seleccione</option><option v-for="h in horarios" :key="h.id" :value="h.id">[{{h.codigo}}] {{h.descripcion}} — {{time(h.entrada_1)}}/{{time(h.salida_1)}}</option></select></label><footer><button class="soft" @click="editing=null">Cancelar</button><button :disabled="saving" @click="save">{{saving?'Guardando…':'Guardar cambio'}}</button></footer></section></div></div></template>
<style scoped>
