r-radius:11px;background:#fff}.modal>header,.modal>footer{padding:14px;display:flex;align-items:center;justify-content:space-between}.modal h2{margin:2px 0;font-size:1rem}.modal>header button{color:#64727a;background:#edf1f3;font-size:1rem}.current{margin:0 14px;padding:12px;display:grid;gap:5px;background:#f1f5f6;font-size:.52rem}.current small{color:#748188}.modal label{margin:14px;display:grid;gap:6px;font-size:.52rem;font-weight:700}.modal>footer{justify-content:flex-end;gap:7px}@media(max-width:700px){.facts{grid-template-columns:1fr 1fr}.filters{grid-template-columns:1fr}.hero p{display:none}}
